import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { crossDissolve, cameraDrift } from "../transitions";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
} from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

// Semantic status colors — data traffic light ONLY
const STATUS = {
  validBg: "#123322",
  validBorder: "#2f9e5f",
  validText: "#5fd48a",
  invalidBg: "#3a1414",
  invalidBorder: "#d24b4b",
  invalidText: "#f08a8a",
  catchBg: "#3a2c10",
  catchBorder: "#d99a2b",
  catchText: "#f0c46b",
};

const TRANSITION = Math.round(10 * fps / 25);

const FONT = "'GT Walsheim', Inter, sans-serif";
const FONT_BODY = "Inter, sans-serif";
const FONT_MONO = "monospace";

// Scene durations
const S1 = 200;
const S2 = 200;
const S3 = 350;
const S4 = 300;
const S5 = 220;

export const durationInFrames =
  S1 + S2 + S3 + S4 + S5 + 5 * TRANSITION - 4 * TRANSITION;

// ============ BACKGROUND ============
const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/Back_Dark.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

// ============ SHARED: Caption ============
const Caption: React.FC<{ text: string; delay?: number }> = ({
  text,
  delay = 4,
}) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();
  const inP = springIn(frame, f, delay, "GENTLE");
  const drift = ambientDrift(frame, 1.5, 120, "caption" + text.slice(0, 6));
  return (
    <div
      style={{
        position: "absolute",
        left: "50%",
        bottom: "8%",
        transform: `translate(-50%, ${interpolate(inP, [0, 1], [24, 0]) + drift}px)`,
        opacity: inP,
        maxWidth: "72%",
        textAlign: "center",
        fontFamily: FONT_BODY,
        fontWeight: 400,
        fontSize: 46,
        lineHeight: 1.3,
        color: COLORS.text,
        backgroundColor: COLORS.card,
        border: `1px solid ${COLORS.border}`,
        borderRadius: 20,
        padding: "24px 44px",
        boxShadow: "0 24px 64px rgba(0,0,0,0.5)",
      }}
    >
      {text}
    </div>
  );
};

// ============ SHARED: Sender Window ============
type MailRow = {
  to: string;
  state: "failed" | "sending" | "delivered";
  revealAt: number;
};

const StatusPip: React.FC<{ kind: "failed" | "delivered"; progress: number }> = ({
  kind,
  progress,
}) => {
  const isFail = kind === "failed";
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 14,
        opacity: progress,
      }}
    >
      <div
        style={{
          width: 20,
          height: 20,
          borderRadius: "50%",
          backgroundColor: isFail ? STATUS.invalidText : STATUS.validText,
        }}
      />
      <span
        style={{
          fontFamily: FONT,
          fontWeight: 600,
          fontSize: 30,
          color: isFail ? STATUS.invalidText : STATUS.validText,
        }}
      >
        {isFail ? "Delivery failed" : "Delivered"}
      </span>
    </div>
  );
};

const SenderWindow: React.FC<{
  mode: "hook" | "healthy";
  rows: MailRow[];
  counterTarget: number;
  counterLabel: string;
  counterColor: string;
  chipText: string;
  chipColor: { bg: string; border: string; text: string };
  chipDelay: number;
}> = ({
  mode,
  rows,
  counterTarget,
  counterLabel,
  counterColor,
  chipText,
  chipColor,
  chipDelay,
}) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  const counterP = springIn(frame, f, 20, "LIQUID");
  const counterVal = Math.round(interpolate(counterP, [0, 1], [0, counterTarget]));
  const chipIn = springIn(frame, f, chipDelay, "ELASTIC");

  return (
    <div
      style={{
        width: 1700,
        backgroundColor: COLORS.card,
        border: `1px solid ${COLORS.border}`,
        borderRadius: 28,
        boxShadow: "0 30px 80px rgba(0,0,0,0.5)",
        overflow: "hidden",
      }}
    >
      {/* Title bar */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 18,
          padding: "26px 40px",
          borderBottom: `1px solid ${COLORS.border}`,
        }}
      >
        <div style={{ width: 18, height: 18, borderRadius: "50%", backgroundColor: "#5a5c60" }} />
        <div style={{ width: 18, height: 18, borderRadius: "50%", backgroundColor: "#5a5c60" }} />
        <div style={{ width: 18, height: 18, borderRadius: "50%", backgroundColor: "#5a5c60" }} />
        <span
          style={{
            fontFamily: FONT,
            fontWeight: 600,
            fontSize: 32,
            color: COLORS.textMuted,
            marginLeft: 16,
          }}
        >
          Outreach — 5,000 leads
        </span>
      </div>

      {/* Rows */}
      <div style={{ padding: "20px 40px" }}>
        {rows.map((r, i) => {
          const rp = springIn(frame, f, r.revealAt, "GENTLE");
          const isFail = r.state === "failed";
          const rowBg =
            mode === "hook" && isFail
              ? STATUS.invalidBg
              : mode === "healthy"
              ? STATUS.validBg
              : COLORS.card;
          const rowBorder =
            mode === "hook" && isFail
              ? STATUS.invalidBorder
              : mode === "healthy"
              ? STATUS.validBorder
              : COLORS.border;
          return (
            <div
              key={i}
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                padding: "22px 28px",
                marginBottom: 14,
                borderRadius: 16,
                backgroundColor: rowBg,
                border: `1px solid ${rowBorder}`,
                opacity: rp,
                transform: `translateX(${interpolate(rp, [0, 1], [-30, 0])}px)`,
              }}
            >
              <span
                style={{
                  fontFamily: FONT_MONO,
                  fontSize: 30,
                  color: COLORS.textMuted,
                }}
              >
                {r.to}
              </span>
              <StatusPip
                kind={mode === "hook" ? "failed" : "delivered"}
                progress={rp}
              />
            </div>
          );
        })}
      </div>

      {/* Footer: counter + reputation chip */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "28px 40px",
          borderTop: `1px solid ${COLORS.border}`,
        }}
      >
        <div style={{ display: "flex", alignItems: "baseline", gap: 16 }}>
          <span
            style={{
              fontFamily: FONT,
              fontWeight: 600,
              fontSize: 60,
              color: counterColor,
              fontVariantNumeric: "tabular-nums",
            }}
          >
            {counterVal.toLocaleString("en-US")}
          </span>
          <span
            style={{
              fontFamily: FONT_BODY,
              fontSize: 32,
              color: COLORS.textSubtle,
            }}
          >
            {counterLabel}
          </span>
        </div>

        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 14,
            padding: "16px 32px",
            borderRadius: 999,
            backgroundColor: chipColor.bg,
            border: `1px solid ${chipColor.border}`,
            opacity: chipIn,
            transform: `scale(${interpolate(chipIn, [0, 1], [0.85, 1])})`,
          }}
        >
          <div
            style={{
              width: 18,
              height: 18,
              borderRadius: "50%",
              backgroundColor: chipColor.text,
            }}
          />
          <span
            style={{
              fontFamily: FONT,
              fontWeight: 600,
              fontSize: 30,
              color: chipColor.text,
            }}
          >
            {chipText}
          </span>
        </div>
      </div>
    </div>
  );
};

// ============ SCENE 1: HOOK ============
const HOOK_ROWS: MailRow[] = [
  { to: "hello@northstar.io", state: "failed", revealAt: 30 },
  { to: "contact@brightlane.co", state: "failed", revealAt: 45 },
  { to: "info@meridianlabs.com", state: "failed", revealAt: 60 },
  { to: "sales@quantumreach.io", state: "failed", revealAt: 75 },
];

const SceneHook: React.FC = () => {
