// ============ SCENE 3: THE TOGGLE ============
type OutRow = { name: string; email: string; status: "valid" | "invalid" | "catch-all"; at: number };
const OUT_ROWS: OutRow[] = [
  { name: "Bright Dental", email: "care@brightdental.com", status: "valid", at: 200 },
  { name: "Lane Coffee", email: "hi@lanecoffee.io", status: "catch-all", at: 214 },
  { name: "Meridian Labs", email: "info@meridianlabs.com", status: "invalid", at: 228 },
  { name: "Quantum Reach", email: "sales@quantumreach.io", status: "valid", at: 242 },
];

const statusStyle = (s: OutRow["status"]) => {
  if (s === "valid")
    return { bg: STATUS.validBg, border: STATUS.validBorder, text: STATUS.validText };
  if (s === "invalid")
    return { bg: STATUS.invalidBg, border: STATUS.invalidBorder, text: STATUS.invalidText };
  return { bg: STATUS.catchBg, border: STATUS.catchBorder, text: STATUS.catchText };
};

const Toggle: React.FC<{ on: number; label: string; tag?: string }> = ({
  on,
  label,
  tag,
}) => {
  const knobX = interpolate(on, [0, 1], [0, 52]);
  const trackColor = interpolate(on, [0, 1], [0, 1]);
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        padding: "30px 36px",
        borderRadius: 18,
        backgroundColor: COLORS.card,
        border: `1px solid ${COLORS.border}`,
        marginBottom: 22,
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 24 }}>
        <span
          style={{
            fontFamily: FONT,
            fontWeight: 600,
            fontSize: 46,
            color: COLORS.text,
          }}
        >
          {label}
        </span>
        {tag && (
          <span
            style={{
              fontFamily: FONT_BODY,
              fontSize: 28,
              color: COLORS.orange,
              border: `1px solid ${COLORS.orange}`,
              borderRadius: 999,
              padding: "8px 20px",
              opacity: on,
            }}
          >
            {tag}
          </span>
        )}
      </div>
      <div
        style={{
          width: 108,
          height: 56,
          borderRadius: 999,
          backgroundColor: `rgba(248,102,6,${trackColor})`,
          border: `2px solid ${on > 0.5 ? COLORS.orange : COLORS.border}`,
          position: "relative",
          transition: "none",
        }}
      >
        <div
          style={{
            position: "absolute",
            top: 4,
            left: 4,
            width: 44,
            height: 44,
            borderRadius: "50%",
            backgroundColor: COLORS.text,
            transform: `translateX(${knobX}px)`,
          }}
        />
      </div>
    </div>
  );
};

