      <Caption
        text="Flip Email verification — every address comes back tagged valid, invalid, or catch-all."
        delay={40}
      />
    </AbsoluteFill>
  );
};

// ============ SCENE 4: THE SKILL ============
const PROMPT = "dental practices in Austin — 5 contacts each, verified emails → Google Sheets";

const SHEET_ROWS = [
  { name: "Austin Family Dental", email: "info@austinfamilydental.com" },
  { name: "Barton Springs Dental", email: "hello@bartonspringsdental.com" },
