      <div
        style={{
          position: "absolute",
          right: "5%",
          top: "22%",
          width: 1350,
          backgroundColor: COLORS.card,
          border: `1px solid ${COLORS.border}`,
          borderRadius: 28,
          overflow: "hidden",
          opacity: sheetIn,
          transform: `translateY(${interpolate(sheetIn, [0, 1], [40, drift])}px)`,
          boxShadow: "0 30px 80px rgba(0,0,0,0.5)",
        }}
      >
        <div
          style={{
            padding: "30px 40px",
            borderBottom: `1px solid ${COLORS.border}`,
            fontFamily: FONT,
            fontWeight: 600,
            fontSize: 38,
            color: COLORS.textMuted,
          }}
